import dataclasses

from yib import yconsole


console = yconsole.Console(stderr=True)


@dataclasses.dataclass
class Package:
    pypi: str
    # The crawler will crawl URLs with the same prefix until the last slash.
    index_url: str
    namespaces: list[str] = dataclasses.field(default_factory=list)
    exclude_root_urls: list[str] = dataclasses.field(default_factory=list)
    # A Sphinx inventory to merge into the mapping, e.g. "https://foo.dev/objects.inv".
    objects_inv_url: str | None = None
    # Mine the import statements out of the code examples. Only worth enabling for
    # hand-written docs that have no per-symbol anchors to crawl.
    parse_documented_imports: bool = False
    indexed: bool = True
    # Skip crawling/updating this package's docs.
    do_not_update: bool = False
    do_not_update_reason: str = ""

    def __post_init__(self):
        if not self.namespaces:
            self.namespaces = [self.pypi.replace("-", "_")]
        if self.do_not_update and not self.do_not_update_reason:
            raise ValueError(
                f"{self.pypi}: do_not_update_reason must be set when do_not_update "
                "is True"
            )

    def is_cpython(self):
        return self.pypi == "python"


